jump() {
        const s = this.inlineEditState.get();
        if (!s) {
            return;
        }
        transaction(tx => {
            this.dontRefetchSignal.trigger(tx);
            this.H.setPosition(s.inlineEdit.range.getStartPosition(), 'inlineCompletions.jump');
            this.H.revealLine(s.inlineEdit.range.startLineNumber);
            this.H.focus();
        });
    }
